    int in_str = 0, state = 0;
    char key[64], val[64];
    int k_len = 0, v_len = 0;
    for (int i = 0; i < len; i++) {
        char c = json[i];
        if (c == '"') {
            in_str = !in_str;
            continue;
        }
        if (in_str) {
            if (state == 0 && k_len < 63) key[k_len++] = c;
            else if (state == 1 && v_len < 63) val[v_len++] = c;
        } else {
            if (c == ':') {
                state = 1;
                key[k_len] = '\0';
            } else if (c == ',' || c == '}') {
                val[v_len] = '\0';
                if (k_len > 0) {
                    printf("  Key: \"%-16s\" -> Value: \"%s\"\n", key, val);
                }
                k_len = 0;
                v_len = 0;
                state = 0;
            }
        }
    }
}

