    int interval;
    int is_active;
    char name[32];
} Timer;

static Timer timers[MAX_TIMERS];
static int total_timers = 0;
static int current_tick = 0;

static void clear_input(void) {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
