                if (timers[i].ticks_remaining <= 0) {
                    printf("  >>> Timer #%d ('%s') FIRED callback!\n", timers[i].id, timers[i].name);
                    timers[i].ticks_remaining = timers[i].interval;
                    fired++;
                }
            }
        }
