        BTreeNode* s = create_node(0);
        s->C[0] = root;
        split_child(s, 0, root);
        int i = 0;
        if (s->keys[0] < k) i++;
        insert_non_full(s->C[i], k);
        return s;
    } else {
        insert_non_full(root, k);
        return root;
    }
}

